#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

# ── wizard-specific helpers ────────────────────────────────────────────────
#
# Everything below is about gh on the human's own machine: where the binary
# lives, whether the package manager is present, and how a freshly installed
# gh becomes findable without restarting the shell.

OS_NAME="$(uname -s 2>/dev/null || echo unknown)"
IS_WINDOWS=0
case "$OS_NAME" in
  MINGW*|MSYS*|CYGWIN*) IS_WINDOWS=1 ;;
esac

# MSI 包名带架构：ARM64 机器要下 _arm64.msi，不能一律当成 amd64。
case "$(uname -m 2>/dev/null || echo x86_64)" in
  arm64|aarch64) MSI_ARCH="arm64" ;;
  *)             MSI_ARCH="amd64" ;;
esac

has() { command -v "$1" >/dev/null 2>&1; }

# _find_gh locates gh even when this shell's PATH predates the install
# (winget/brew/MSI put it somewhere the current process never re-read).
# Sets GH_EXE on success.
GH_EXE=""
_find_gh() {
  if has gh; then GH_EXE="$(command -v gh)"; return 0; fi
  local candidate
  for candidate in \
    "/c/Program Files/GitHub CLI/gh.exe" \
    "${HOME:-${USERPROFILE:-/nonexistent}}/AppData/Local/Microsoft/WinGet/Links/gh.exe" \
    "/usr/local/bin/gh" \
    "/opt/homebrew/bin/gh" \
    "/home/linuxbrew/.linuxbrew/bin/gh"; do
    if [[ -x "$candidate" ]]; then GH_EXE="$candidate"; return 0; fi
  done
  return 1
}

# gh_ready makes gh callable for the rest of this run: finds it, then prepends
# its directory to PATH so `gh ...` below just works.
gh_ready() {
  _find_gh || return 1
  case ":$PATH:" in
    *":$(dirname "$GH_EXE"):"*) ;;
    *) PATH="$(dirname "$GH_EXE"):$PATH"; export PATH ;;
  esac
  return 0
}

# _install_msi hands the official installer page to the human and waits.
_install_msi() {
  open_url "https://github.com/cli/cli/releases/latest"
  step "在 Releases 页找最新的 gh_*_windows_${MSI_ARCH}.msi（是 .msi，不是 .zip）并下载。"
  step "双击安装包，一路 Next 到 Finish（默认选项即可）。"
  pause "装完了按 Enter 继续"
}

# ── the wizard itself ─────────────────────────────────────────────────────
banner "GitHub CLI（gh）安装向导"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "环境检查"
say "先看清这台机器上已经有什么，再决定怎么装。"
note "系统      : ${OS_NAME} $(uname -m 2>/dev/null || echo '')"
if gh_ready; then
  note "gh        : 已安装 → ${GH_EXE}"
  note "版本      : $(gh --version 2>/dev/null | head -n1)"
else
  note "gh        : 未安装"
fi
if has winget; then
  note "winget    : 可用（首选安装方式）"
else
  note "winget    : 不可用"
fi
if has brew; then note "brew      : 可用"; fi
if has scoop; then note "scoop     : 可用"; fi
if has choco; then note "choco     : 可用"; fi
pause "按 Enter 继续"

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "官方安装页：确认安装方式"
say "官方安装说明都在这里，向导会按下面的方式替你执行。"
open_url "https://cli.github.com/"
note "手动访问也是同一个地址：https://cli.github.com/"

if gh_ready; then
  METHOD="none"
  note "已经装好 gh，安装阶段会自动跳过，只做验证和登录。"
elif (( IS_WINDOWS )) && has winget; then
  METHOD="winget"
  note "方式：winget（官方仓库里的 GitHub.cli 包）→ 一条命令装完"
elif (( IS_WINDOWS )); then
  METHOD="msi"
  note "方式：官方 MSI 安装包 → 下载后双击安装（这台机器没有 winget）"
elif has brew; then
  METHOD="brew"
  note "方式：Homebrew → brew install gh"
elif [[ "$OS_NAME" == Darwin* ]]; then
  METHOD="macos"
  note "方式：macOS 官方安装说明（推荐先装 Homebrew，再 brew install gh）"
else
  METHOD="linux"
  note "方式：发行版包管理器 → 见官方 Linux 安装说明"
fi

step "页面上有 Windows / macOS / Linux 三栏，可以顺手核对一下。"
pause "按 Enter 继续"

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "安装 GitHub CLI"
case "$METHOD" in
  none)
    note "已安装，跳过本阶段。"
    ;;
  winget)
    say "即将执行："
    say "  winget install --id GitHub.cli --exact --source winget"
    warn "winget 可能弹出 UAC 提权窗口，点「是」即可。"
    pause "按 Enter 开始安装（可能要几十秒）"
    if winget install --id GitHub.cli --exact --source winget \
         --accept-package-agreements --accept-source-agreements; then
      note "winget 报告安装成功。"
    else
      warn "winget 安装失败，改用官方 MSI 安装包。"
      warn "没有管理员权限的话，也可以先装 scoop 再用：scoop install gh"
      _install_msi
    fi
    ;;
  msi)
    _install_msi
    ;;
  brew)
    say "即将执行：brew install gh"
    pause "按 Enter 开始安装"
    if brew install gh; then
      note "brew 报告安装成功。"
    else
      warn "brew 安装失败，请按官方页面手动安装后重新运行本向导。"
    fi
    ;;
  macos)
    open_url "https://github.com/cli/cli/blob/trunk/docs/install_macos.md"
    step "按页面里 Homebrew 那一段：先装 Homebrew，再 brew install gh。"
    pause "装完了按 Enter 继续"
    ;;
  linux)
    open_url "https://github.com/cli/cli/blob/trunk/docs/install_linux.md"
    step "按页面里你所用发行版的那一段，执行 apt/dnf/pacman 等安装命令。"
    pause "装完了按 Enter 继续"
    ;;
esac

# A fresh install lands outside this process's PATH: re-find it now.
hash -r 2>/dev/null || true
if gh_ready; then
  note "本会话已找到 gh → ${GH_EXE}"
else
  warn "当前 shell 还找不到 gh，下一个阶段会重试并给出处理办法。"
fi

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "验证安装"
if gh_ready; then
  say "$(gh --version 2>&1 | head -n1)"
  step "能看到 gh version x.y.z 就算装好了。"
else
  warn "这个终端里还找不到 gh。"
  step "最常见原因：装完后当前 Git Bash 窗口没重新读 PATH。"
  step "关掉这个窗口，重新打开 Git Bash，再运行：bash scripts/install-gh-cli.sh"
  step "仍不行就手动把安装目录加到 PATH（通常在 C:\\Program Files\\GitHub CLI）。"
  pause "按 Enter 结束向导"
  exit 1
fi
pause "按 Enter 继续"

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "登录 GitHub"
if gh auth status >/dev/null 2>&1; then
  note "已经登录过，跳过本阶段。"
  gh auth status 2>&1 | sed 's/\r$//; s/^/  /' || true
else
  say "一键登录：gh 会给出一个一次性验证码（形如 ABCD-1234），并尝试打开浏览器。"
  step "浏览器里登录 github.com。"
  step "把终端里显示的一次性验证码粘进去 → Continue → Authorize。"
  warn "如果浏览器没自动打开，就手动访问 gh 提示的 https://github.com/login/device 并粘贴验证码。"
  pause "准备好了按 Enter（gh 随后还会要你再按一次 Enter 打开浏览器）"
  if gh auth login --hostname github.com --git-protocol https --web; then
    note "gh 报告登录成功。"
  else
    warn "登录没有完成。可以稍后手动运行：gh auth login"
  fi
fi

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "校验认证并配置 git 凭据"
if gh auth status >/dev/null 2>&1; then
  gh auth status 2>&1 | sed 's/\r$//; s/^/  /' || true
  say ""
  if gh auth setup-git; then
    note "已让 git 使用 gh 作为 GitHub 的凭据助手（git push 不再反复要密码）。"
  else
    warn "gh auth setup-git 失败，可手动执行一次。"
  fi
  GITHUB_USER="$(gh api user --jq .login 2>/dev/null || true)"
  if [[ -n "${GITHUB_USER:-}" ]]; then
    note "登录账号：${GITHUB_USER}"
  fi
else
  warn "当前仍未登录，跳过凭据配置。"
  step "之后可以随时运行：gh auth login && gh auth setup-git"
fi
pause "按 Enter 继续"

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "小结与常用命令"
if gh_ready; then
  say "gh 位置：${GH_EXE}"
  say "版本    ：$(gh --version 2>/dev/null | head -n1)"
fi
if gh auth status >/dev/null 2>&1; then
  say "登录    ：已认证 github.com"
else
  say "登录    ：尚未认证（gh auth login）"
fi
say ""
step "gh auth status            查看登录状态"
step "gh repo clone owner/repo  克隆仓库"
step "gh pr create              开 Pull Request"
step "gh pr list                列出 PR"
step "gh issue list             列出 issue"
step "gh run list --watch       看 Actions 运行"
note "全部命令：gh help / https://cli.github.com/manual/"

# 最后一行刻意不调用 finish：finish 会 _clear 屏，把上面这张小结和命令表冲掉，
# 而这个向导没有 .env / GitHub secret 需要汇总。
printf '\n  %s%s✓ 完成：GitHub CLI 已可在这台机器上使用。%s\n' "$BOLD" "$GREEN" "$RESET"
printf '  %s重跑本脚本是安全的：已安装、已登录的状态会自动跳过。%s\n\n' "$DIM" "$RESET"
